ee:message.ee:set-payload:
%dw 2.0
output application/json

var error = vars.vErrorMsg default {}

fun safe(val) =
    if (val is Array)
        (val map (item) -> 
            if (item is String) item 
            else write(item, "application/json")
        ) joinBy ", "
    else
        (val default "-") as String

fun formatDateTime(dt) =
    if (dt != null)
        ((dt as DateTime) as String {format: "yyyy-MM-dd HH:mm:ss"})
    else "-"

fun formatList(arr) =
    if (arr is String)
        arr
    else if (!isEmpty(arr default []))
        ((arr default []) map (item) -> 
            if (item is String) item 
            else write(item, "application/json")
        ) joinBy "<br/>"
    else "-"

---
{
  message: {
    subject: "Missing Attachments for Automation",
    importance: "high",
    body: {
      contentType: "HTML",
      content:
        "<html><body style='font-family: Arial, sans-serif; font-size:13px;'>" ++

        "<p>Hi Team,</p>" ++

        "<p>This is to inform you that the <b>Inventory and Rack Reports</b> processing has <b>FAILED</b> due to missing required documents.</p>" ++

        "<table border='1' cellpadding='8' cellspacing='0' style='border-collapse: collapse;'>" ++
          "<tr style='background-color:#f2f2f2;'>" ++
            "<th align='left'>Field</th><th align='left'>Value</th>" ++
          "</tr>" ++

          "<tr><td><b>Automation Status</b></td><td><b>FAILED</b></td></tr>" ++
          "<tr><td><b>Environment</b></td><td>" ++ safe(p('mule.env') default "PROD") ++ "</td></tr>" ++
          "<tr><td><b>Correlation ID</b></td><td>" ++ safe(vars.vCorrelationId) ++ "</td></tr>" ++
          "<tr><td><b>Failure Reason</b></td><td>Missing Required Documents</td></tr>" ++
          "<tr><td><b>Missing Documents</b></td><td>" ++ formatList(vars.missingDocNames) ++ "</td></tr>" ++
          "<tr><td><b>Error Type</b></td><td>" ++ safe(error.ErrorType) ++ "</td></tr>" ++
          "<tr><td><b>Error Message</b></td><td><b>" ++ safe(error.ErrorMessage) ++ "</b></td></tr>" ++
          "<tr><td><b>Failing Component</b></td><td>Attachments Validation</td></tr>" ++
		  "<tr><td><b>Email Received Date Time (UTC)</b></td><td>" ++ formatDateTime(vars.vReceivedDatetime) ++ "</td></tr>" ++
          "<tr><td><b>Execution Timestamp (UTC)</b></td><td>" ++ formatDateTime(vars.currentExecutionDateTime) ++ "</td></tr>" ++

        "</table><br/>" ++

        "<p><b>Action Required:</b> Please resend the email with all required attachments to proceed with processing.</p>" ++

        "<br/>" ++
        "<p>Thank you,<br/>Automation Team</p>" ++

        "<p style='font-size:12px;color:gray;'>This is an automated email generated by the Mulesoft Automation. Please do not reply.</p>" ++

        "</body></html>"
    },

    toRecipients: p('mail.to') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },

    ccRecipients: p('mail.cc') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }
  },

  saveToSentItems: false
}

