ee:variables.ee:set-variable:
%dw 2.0 output application/json
fun formatDateTime(dt) = if (dt != null) ((dt as DateTime) as String {format: "yyyy-MM-dd HH:mm:ss"}) else "-"
fun cleanJsonString(val) = (write(val, "application/json") replace "\n" with "" replace "\\" with "") --- { "Info":"Automation Failed", "DocumentName": cleanJsonString(vars.allDOCs), "InventoryDate": vars.inventoryDate, "CorrelationId": vars.vCorrelationId, "ErrorType": (error.errorType.namespace) ++ ":" ++ (error.errorType.identifier), "ErrorMessage": error.description, "FailingComponent": error.failingComponent, "ExecutionTimestamp(UTC)": formatDateTime(vars.currentExecutionDateTime) }

